        copy.query.groupBy(School.__TeaqlFields.VERSION_PROPERTY_member, as: alias)
        return copy
    }

    private func adding(_ expression: TeaQLExpression) -> Self {
        var copy = self
        copy.query.filter = copy.query.filter.map { .and([$0, expression]) } ?? expression
        return copy
    }

    private func removingActiveVersionFilter(
        _ expression: TeaQLExpression?
    ) -> TeaQLExpression? {
        guard let expression else { return nil }
        let active = TeaQLExpression.greaterThanOrEqual("version", .int(1))
        if expression == active { return nil }
        guard case .and(let items) = expression else { return expression }
        let retained = items.compactMap { removingActiveVersionFilter($0) }
        if retained.isEmpty { return nil }
        if retained.count == 1 { return retained[0] }
        return .and(retained)
    }
}

public extension SchoolRequest where State == RequestExecutable {
    private func ensureIntent() throws {
        _ = try QueryIntent(comment: query.comment, purpose: query.purpose)
    }

    func newEntity(_ context: UserContext) async throws -> School {
        try ensureIntent()
        let id = try await context.generateInternalID(for: "School")
        return context.initializeEntity("School", try School.teaqlNewWithID(id))
    }

    func executeForList(_ context: UserContext) async throws -> SmartList<School> {
        try ensureIntent()
        let snapshots = LoadedEntitySnapshots()
        return try await context.executeTypedList(query, countRequested: countRequested) { record, relations in
            try School.from(record: record, root: EntityRoot(), snapshots: snapshots,
                relations: relations)
        }
    }

    func executeForOne(_ context: UserContext) async throws -> School? {
        var request = self
        request.query.limit = 1
        return try await request.executeForList(context).first
    }

    /// Pull-based typed stream. Each demand loads at most one bounded chunk;
    /// no task eagerly buffers the entire query into a SmartList.
    func executeForStream(_ context: UserContext) throws -> AsyncThrowingStream<School, Error> {
        try ensureIntent()
        guard query.groupBy.isEmpty && query.aggregates.isEmpty else {
            throw TeaQLError.unsupportedQueryCapability("entity streams require an entity query")
        }
        var source = query
        if !source.orderBy.contains(where: { $0.field == "id" }) { source.orderBy.append(OrderBy("id", .ascending)) }
        let request = try QueryRequest(query: source)
        let cursor = SchoolStreamCursor(offset: source.offset, remaining: source.limit) { offset, limit in
            var page = request.query; page.offset = offset; page.limit = limit
            let result = try await context.execute(request.withQuery(page))
            let snapshots = LoadedEntitySnapshots()
            return try result.records.map {
                try School.from(record: $0, root: EntityRoot(), snapshots: snapshots)
            }
        }
        return AsyncThrowingStream(unfolding: { try await cursor.next() })
    }

    func executeForRows(_ context: UserContext) async throws -> SmartList<TeaQLRecord> {
        try ensureIntent()
        let result = try await context.execute(QueryRequest(query: query))
        return SmartList(result.records, facets: result.facets)
    }


}

private actor SchoolStreamCursor {
    private var offset: Int
    private var remaining: Int?
    private var buffer: [School] = []
    private var index = 0
    private var finished = false
    private let fetch: @Sendable (Int, Int) async throws -> [School]

    init(offset: Int, remaining: Int?, fetch: @escaping @Sendable (Int, Int) async throws -> [School]) {
        self.offset = offset; self.remaining = remaining; self.fetch = fetch
    }

    func next() async throws -> School? {
        try _Concurrency.Task<Never, Never>.checkCancellation()
        if index == buffer.count {
            guard !finished else { return nil }
            let size = min(128, remaining ?? 128)
            guard size > 0 else { finished = true; return nil }
            buffer = try await fetch(offset, size); index = 0
            offset += buffer.count
            if let count = remaining { remaining = count - buffer.count }
            finished = buffer.count < size || remaining == 0
            guard !buffer.isEmpty else { return nil }
        }
        defer { index += 1 }
        return buffer[index]
    }
}